import Swiper from "swiper";
import { Waterfall } from "types/waterfall";

export function printDebug(debug: boolean, str: string, el: unknown) {
  if (!debug) return;
  console.log(`${str}:`, el);
}

export function getUniqueClasses(targetElement: HTMLElement, comparisonElement: HTMLElement): string {
  if (!targetElement.classList || !comparisonElement.classList) return "";

  const targetClasses = Array.from(targetElement.classList || []);
  const comparisonClasses = Array.from(comparisonElement.classList || []);

  const filtered = targetClasses.filter((className) => className && !comparisonClasses.includes(className));

  return filtered.length > 0 ? filtered.join(" ") : "";
}

// ✅ Parse attribute as string (ignoring default value)
export function parseString(el: HTMLElement, attrName: string, defaultValue?: string): string | undefined {
  const attrValue = el.getAttribute(attrName)?.trim();
  if (!attrValue || attrValue === defaultValue) return undefined;
  return attrValue;
}

export function parseSlidesPerView(
  el: HTMLElement,
  attrName: string,
  defaultValue?: number,
): number | "auto" | undefined {
  const attrValue = el.getAttribute(attrName)?.trim();
  if (!attrValue) return undefined;

  if (attrValue.toLowerCase() === "auto") return "auto";

  const parsedValue = Number(attrValue);
  const validAndUnique = isNaN(parsedValue) || parsedValue === defaultValue;
  if (validAndUnique) return undefined;
  return parsedValue;
}

// Returns the raw attribute value, typed as whatever the call site expects (Swiper string/number unions).
export function parseAny<T extends string | number = string>(
  el: HTMLElement,
  attrName: string,
  defaultValue?: string,
): T | undefined {
  const attrValue = el.getAttribute(attrName)?.trim();
  if (!attrValue || attrValue === defaultValue) return undefined;
  return attrValue as unknown as T;
}

// ✅ Parse attribute as number
export function parseNumber(el: HTMLElement, attrName: string, defaultValue?: number): number | undefined {
  const attrValue = el.getAttribute(attrName)?.trim();
  if (!attrValue) return undefined;

  const parsedValue = Number(attrValue);
  const validAndUnique = isNaN(parsedValue) || parsedValue === defaultValue;
  if (validAndUnique) return undefined;
  return parsedValue;
}

// ✅ Parse attribute as boolean
export function parseBoolean(el: HTMLElement, attrName: string, defaultValue?: boolean): boolean | undefined {
  const attrValue = el.getAttribute(attrName)?.trim()?.toLowerCase();
  if (!attrValue) return undefined;

  if (attrValue === "true") return defaultValue === true ? undefined : true;
  if (attrValue === "false") return defaultValue === false ? undefined : false;

  return undefined;
}

function isHTMLElement(value: unknown): value is HTMLElement {
  return typeof HTMLElement !== "undefined" && value instanceof HTMLElement;
}

export function removeNullOrUndefinedKeys<T extends object>(obj: T): T {
  if (typeof obj !== "object" || obj === null) return obj;

  const record = obj as Record<string, unknown>;
  for (const key in record) {
    const value = record[key];
    if (value === null || value === undefined) {
      delete record[key];
    } else if (typeof value === "object" && value !== null && !isHTMLElement(value)) {
      removeNullOrUndefinedKeys(value as Record<string, unknown>);
      if (Object.keys(value).length === 0) delete record[key];
    }
  }

  return obj;
}

export function getWaterfallByName(waterfalls: Waterfall[], name: string): Waterfall | undefined {
  return waterfalls.find((w) => w.name?.toLowerCase() === name?.toLowerCase());
}

export function findWaterfallByName(waterfalls: Waterfall[], name: string, element?: Element): Waterfall | null {
  const waterfall = getWaterfallByName(waterfalls, name);
  if (!waterfall) {
    console.warn(`[MANIPULATION] No Waterfall found with name: "${name}"`, element);
    return null;
  }
  if (!waterfall.swiper) {
    console.error(`[MANIPULATION] Invalid Swiper instance in Waterfall "${name}"`);
    return null;
  }
  return waterfall;
}

export function getWaterfallsByName(waterfalls: Waterfall[], selector: string, debug: boolean): Swiper[] {
  const matchedWaterfalls = waterfalls
    .filter((w) => {
      const match = w.name?.toLowerCase() === selector?.toLowerCase();
      return match;
    })
    .map((w) => w.swiper);

  if (debug) console.log(`📊 Found ${matchedWaterfalls.length} matching waterfall(s) for "${selector}"`);

  return matchedWaterfalls;
}

export function fixWebflowCMSListARIARole() {
  document.querySelectorAll('[waterfall] .swiper-wrapper[role="list"]').forEach((wrapper) => {
    wrapper.removeAttribute("role");
  });
}
